import unittest
from solution import word_freq

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(word_freq("A a B"), {"a": 2, "b": 1})
    def test_punct(self):
        self.assertEqual(word_freq("a, a, b"), {"a,": 2, "b": 1})
    def test_empty(self):
        self.assertEqual(word_freq(""), {})
    def test_whitespace(self):
        self.assertEqual(word_freq("x  y	x"), {"x": 2, "y": 1})
